SELECT game_id AS "gameId", phase_id AS "phaseId", ability_id AS "abilityId", phase_order AS "phaseOrder", phase_type_id AS "phaseTypeId", duration_formula_key AS "durationFormulaKey", interruptible AS interruptible, change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.ability_phases WHERE game_id = #{gameId}
AND ability_id = #{abilityId}
ORDER BY ability_id, phase_order
